    let post_ratio = (post / capacity).clamp(0.0, 1.0);
    score += progress * post_ratio * (23.0 + 8.0 * progress);

    // Near the end, closure and very small residues dominate ordinary reuse.
    if progress > 0.78 {
        let closure_bonus = (1.0 - post_ratio) * (progress - 0.78) * 17.0;
        score -= closure_bonus;
        if post > 0.0 && post <= 2.0 {
            score -= (progress - 0.78) * 22.0;
        }
    }

    score
