        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let mut score = post;

    // Residue viability is estimated from both the incoming item and the
    // likely next item.  The nonlinear term increasingly rejects gaps that
    // are large in absolute terms but too small to support a useful sequence.
    let demand = next.max(item).max(2.0);
    let viability = demand * (0.61 + 0.075 * progress);
    if post > 0.0 && post < viability {
        let deficit = viability - post;
        let relative = deficit / viability.max(1.0);
        let curvature = relative * relative * (18.0 + 8.0 * progress);
        score += deficit * (6.8 + 3.4 * progress) + curvature;
    }

    // Closing a bin is strongly preferred, while compact residues are valued
    // in proportion to how readily they can accept a subsequent item.
    if post == 0.0 {
        score -= 46.0;
    } else {
        let fill = ((capacity - residual) / capacity).clamp(0.0, 1.0);
        score -= (capacity - residual).min(item) * 0.17;
        score -= fill * fill * 6.4;

        let compactness = (post / demand).min(1.0);
        score -= compactness * compactness * (5.0 + 2.5 * progress);

        if post <= item.max(2.0) {
            score -= 5.4;
        }

        // A residue just below the next demand is almost as costly as a
        // clearly unusable gap; above the useful band, excess space is
        // penalized with diminishing severity.
        if post < next {
            let scarcity = (next - post) / next.max(1.0);
            score += (next - post) * (3.2 + 1.1 * scarcity);
            score += scarcity * scarcity * 8.0;
        } else {
            let reusable_band = demand * 1.52;
            if post > reusable_band {
                let excess = post - reusable_band;
                let excess_ratio = excess / capacity.max(1.0);
                score += excess.min(capacity * 0.40) * (1.02 + 0.50 * progress);
                score += excess_ratio * 12.0;
            }
        }
    }

    // Below-average residue is more damaging than above-average residue, but
    // use a smooth saturating response so one exceptional bin cannot dominate.
    if mean > 0.0 {
        let delta = residual - mean;
        if delta > 0.0 {
            score += delta * (0.10 + 0.16 * progress);
        } else {
            let normalized = (-delta / mean.max(1.0)).min(1.0);
            score += (-delta) * (0.055 + 0.10 * normalized);
        }
    }

    // Fragmentation becomes increasingly expensive near the end, where there
    // is less remaining stream with which to repair an awkward residue.
    score += open_bins_count as f64 * (0.25 + 0.36 * progress);

    // Preserve scarce fitting capacity unless the placement is close or
    // produces a residue that is plainly difficult to reuse.
    if fitting_bins_count == 1 {
        if post == 0.0 {
            score -= 11.0;
        } else if post < viability {
            score += 13.5;
        } else if post <= item.max(2.0) {
            score -= 5.0;
        } else {
            score += 2.8;
        }
    }

    // Opening is worthwhile only when available bins are structurally poor.
    // The threshold tightens as the stream progresses.
    if residual >= capacity {
        score += 30.0;
        score -= (capacity - item).max(0.0) * 0.045;
        if fitting_bins_count == 0 {
            score -= 21.0;
        } else if fitting_bins_count <= 2 {
            score -= 7.0;
        }
        if progress > 0.72 && fitting_bins_count <= 2 {
            score += (progress - 0.72) * 11.0;
        }
    }

    // Later in the stream, retained space carries a stronger opportunity
    // cost.  This complements the early dead-space penalty rather than
    // replacing it.
    let post_ratio = (post / capacity).clamp(0.0, 1.0);
    score += progress * post_ratio * (20.0 + 8.0 * progress);

    // Near completion, closure and very small residues dominate ordinary
    // reuse, with a sharper end-of-stream switch.
    if progress > 0.82 {
        let closure_bonus = (1.0 - post_ratio) * (progress - 0.82) * 15.0;
        score -= closure_bonus;
        if post > 0.0 && post <= 2.0 {
            score -= (progress - 0.82) * 19.0;
        }
    }

    score
}

